#!/usr/bin/env bash
# Local CORS tests for membership-api (threat 9: only the frontend origin).
#
# Requires the local stack (npx supabase start) and FRONTEND_ORIGINS in
# supabase/functions/.env containing http://127.0.0.1:5500.
# Run from the repository root in Git Bash:   bash tests/cors.sh
#
# Why requests go "direct": the local Kong gateway in front of
# /functions/v1/ has its own CORS plugin that answers every preflight with
# Access-Control-Allow-Origin: * and adds * to responses. That gateway is
# generated by the Supabase CLI and cannot be changed here. To test the
# function's own behaviour, these requests are sent from inside the local
# database container (which has curl) straight to the edge runtime,
# skipping Kong. The last section records what Kong does locally. Hosted
# behaviour must be re-checked after deployment.

set -u

DB_CONTAINER="supabase_db_club-membership-service"
DIRECT="http://supabase_edge_runtime_club-membership-service:8081/membership-api"
eval "$(npx supabase status -o env 2>/dev/null \
  | grep -E '^(API_URL|PUBLISHABLE_KEY)=')"
if [ -z "${API_URL:-}" ] || [ -z "${PUBLISHABLE_KEY:-}" ]; then
  echo "Local stack is not running (npx supabase start)." >&2
  exit 2
fi

GOOD="http://127.0.0.1:5500"
EVIL="https://evil.example"
PASS=0
FAIL=0

# direct CURL_ARGS... -> prints "STATUS|ACAO" (ACAO empty if absent)
direct() {
  docker exec "$DB_CONTAINER" curl -s -o /dev/null -D - "$@" | tr -d '\r' \
    | awk 'BEGIN{IGNORECASE=1; s=""; a=""}
           /^HTTP\//{s=$2}
           tolower($0) ~ /^access-control-allow-origin:/{a=$2}
           END{print s "|" a}'
}

check() {
  if [ "$2" = "$3" ]; then
    PASS=$((PASS + 1)); printf 'PASS  %-50s %s\n' "$1" "$3"
  else
    FAIL=$((FAIL + 1)); printf 'FAIL  %-50s expected %s, got %s\n' "$1" "$2" "$3"
  fi
}

PRE=(-X OPTIONS -H "Access-Control-Request-Method: POST"
     -H "Access-Control-Request-Headers: apikey, content-type")

echo "== CORS tests, function direct"
check "preflight from frontend origin" "204|$GOOD" \
  "$(direct "${PRE[@]}" -H "Origin: $GOOD" "$DIRECT/membership-requests")"
check "preflight from other origin" "403|" \
  "$(direct "${PRE[@]}" -H "Origin: $EVIL" "$DIRECT/membership-requests")"
check "GET /health from frontend origin" "200|$GOOD" \
  "$(direct -H "apikey: $PUBLISHABLE_KEY" -H "Origin: $GOOD" "$DIRECT/health")"
check "GET /health from other origin (no ACAO)" "200|" \
  "$(direct -H "apikey: $PUBLISHABLE_KEY" -H "Origin: $EVIL" "$DIRECT/health")"
check "GET /health with no Origin (no ACAO)" "200|" \
  "$(direct -H "apikey: $PUBLISHABLE_KEY" "$DIRECT/health")"
check "auth error still readable by frontend" "401|$GOOD" \
  "$(direct -H "Origin: $GOOD" "$DIRECT/health")"
check "auth error from other origin (no ACAO)" "401|" \
  "$(direct -H "Origin: $EVIL" "$DIRECT/health")"
check "lookalike origin rejected" "403|" \
  "$(direct "${PRE[@]}" -H "Origin: http://127.0.0.1:55000" "$DIRECT/membership-requests")"

echo "== Local Kong gateway (information only, not counted)"
ACAO="$(curl -s -o /dev/null -D - -X OPTIONS -H "Origin: $EVIL" \
  -H "Access-Control-Request-Method: POST" \
  "$API_URL/functions/v1/membership-api/membership-requests" | tr -d '\r' \
  | grep -i '^access-control-allow-origin:' | head -1 | cut -d' ' -f2)"
echo "INFO  Kong preflight from other origin gives ACAO: ${ACAO:-<none>}"

echo "== $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
